// Traditional switch statement
String result;
switch (day) {
    case MONDAY:
    case FRIDAY:
    case SUNDAY:
        result = "Relax";
        break;
    case TUESDAY:
        result = "Work";
        break;
    case THURSDAY:
    case SATURDAY:
        result = "Party";
        break;
    case WEDNESDAY:
        result = "Study";
        break;
    default:
        result = "Unknown";
}

// Switch expression
String result = switch (day) {
    case MONDAY, FRIDAY, SUNDAY -> "Relax";
    case TUESDAY -> "Work";
    case THURSDAY, SATURDAY -> "Party";
    case WEDNESDAY -> "Study";
    default -> "Unknown";
};

int result = switch (status) {
    case SUCCESS -> {
        logger.info("Operation successful");
        yield 1;
    }
    case ERROR -> {
        logger.error("Operation failed");
        sendAlert();
        yield -1;
    }
    default -> 0;
};

enum Color { RED, GREEN, BLUE }

String shade = switch (color) {
    case RED -> "Warm";
    case GREEN -> "Cool";
    case BLUE -> "Cool";
    // No default needed, all enum values are covered
};

